 q.configure(true,"");q.enqueue(Json::array({target}));check(q.document()["jobs"].size()==1,"old completed automatic cache is queued for current quality policy");auto token=q.start();auto task=q.claim(token);check(task.value("videoQualityPolicy",0)==3&&task.value("qualityUpgradeRevision",0)>0,"quality request is explicit and revision bounded");lease=store.begin(task);check(lease.value("acquired",false)&&lease["taskSlots"]==Json::array({"dynamic"}),"upgrade downloads only dynamic slot");check(store.resolve(target)["assets"]["dynamic"]["id"]==original&&store.resolve(target).value("dynamicReady",false),"old video remains playable while upgrade is pending");
 store.fail(lease);check(store.resolve(target)["assets"]["dynamic"]["id"]==original,"failed upgrade preserves current cache");
 // Advance only this isolated fixture's backoff; a production failure waits.
 auto doc=read(store.root()/L"config"/L"game-media.json");doc["entries"]["steam-570"]["retryAt"]=0;atomicWrite(store.root()/L"config"/L"game-media.json",doc);lease=store.begin(task);lease["videoQualityPolicy"]=3;lease["selectedHeight"]=720;const auto upgraded=store.publish(lease,mp4,false);store.finish(upgraded);q.result(token,"steam-570",true);check(upgraded["assets"]["dynamic"]["qualityPolicy"]==3&&upgraded["assets"]["dynamic"]["selectedHeight"]==720,"published cache records selected 720p policy and playlist resolution");check(!needsVideoQualityUpgrade(store.resolve(target),now()),"current cache is reused without a repeated upgrade");const auto rev=q.snapshot().value("statusRevision",uint64_t{0});for(int n=0;n<30;n++)q.enqueue(Json::array({target}));check(q.snapshot().value("statusRevision",uint64_t{0})==rev,"repeated inventory causes no writes or downloads after upgrade");
 auto manualTarget=target;manualTarget["appId"]=620;auto manual=store.begin(manualTarget);manual=store.publish(manual,mp4,true);manual=store.publish(manual,png,true);check(!needsVideoQualityUpgrade(store.resolve(manualTarget),now()),"manual video is never replaced automatically");q.enqueue(Json::array({manualTarget}));check(q.document()["jobs"].size()==1,"complete manual pair creates no quality job");
 auto removed=store.resolve(target);removed["action"]="delete";removed["slot"]="dynamic";store.edit(removed);check(!needsVideoQualityUpgrade(store.resolve(target),now()),"user deletion remains protected");
 const std::string master="#EXTM3U\n#EXT-X-STREAM-INF:BANDWIDTH=20000000,RESOLUTION=3840x2160\n2160.m3u8\n#EXT-X-STREAM-INF:BANDWIDTH=2000000,RESOLUTION=1920x1080\n1080-low.m3u8\n#EXT-X-STREAM-INF:BANDWIDTH=6000000,RESOLUTION=1920x1080\n1080.m3u8\n#EXT-X-STREAM-INF:BANDWIDTH=1500000,RESOLUTION=1280x720\n720.m3u8\n#EXT-X-STREAM-INF:BANDWIDTH=500000,RESOLUTION=854x480\n480.m3u8\n";const auto plan=hlsPlan(master,"https://video.steamstatic.com/store_trailers/570/master.m3u8");check(plan.variant.ends_with("/720.m3u8")&&plan.height==720,"default HLS prefers 720p over 1080p and 4K");
 const auto full=hlsPlan(master,"https://video.steamstatic.com/master.m3u8",0,1080);check(full.variant.ends_with("/1080.m3u8")&&full.height==1080,"explicit manual 1080p uses full HD and higher bitrate");
 check(hlsPlan(master,"https://video.steamstatic.com/master.m3u8",0,480).height==480,"explicit manual 480p is retained");
 const std::string missing720="#EXTM3U\n#EXT-X-STREAM-INF:BANDWIDTH=6000000,RESOLUTION=1920x1080\n1080.m3u8\n#EXT-X-STREAM-INF:BANDWIDTH=1000000,RESOLUTION=960x540\n540.m3u8\n#EXT-X-STREAM-INF:BANDWIDTH=500000,RESOLUTION=854x480\n480.m3u8\n";
 check(hlsPlan(missing720,"https://video.steamstatic.com/master.m3u8").height==480,"missing 720p prefers 480p rather than 1080p or nonstandard 540p");
 auto preserved=upgraded;preserved["assets"]["dynamic"]["qualityPolicy"]=2;preserved["assets"]["dynamic"]["selectedHeight"]=720;check(!needsVideoQualityUpgrade(preserved,now()),"existing automatic 720p cache needs no redundant replacement");preserved["assets"]["dynamic"]["selectedHeight"]=1080;check(needsVideoQualityUpgrade(preserved,now()),"old automatic 1080p cache aligns with 720p policy");
 for(const auto& [height,expected]:{std::pair{720,720},std::pair{480,480},std::pair{1440,1440}}){const auto text="#EXTM3U\n#EXT-X-STREAM-INF:BANDWIDTH=1000000,RESOLUTION=1920x"+std::to_string(height)+"\nvideo.m3u8\n";check(hlsPlan(text,"https://video.steamstatic.com/master.m3u8").height==expected,"single available source remains usable without invented resolution");}
 const auto capped=hlsPlan(master,"https://video.steamstatic.com/master.m3u8",720);check(capped.height==720,"size fallback selects official 720p");check(hlsPlan(master,"https://video.steamstatic.com/master.m3u8",480).height==480,"second fallback selects official 480p");
 const std::string leaf="#EXTM3U\n#EXT-X-MAP:URI=\"init.mp4\"\n#EXTINF:660.1,\nsegment.m4s\n#EXT-X-ENDLIST\n";const auto longVideo=hlsPlan(leaf,"https://video.steamstatic.com/leaf.m3u8");
 check(hlsExceedsLimit(longVideo,5800000,capacity::maxAssetBytes),"official baseball duration and 1080p bitrate exceed 300 MiB");check(!hlsExceedsLimit(longVideo,2600000,capacity::maxAssetBytes),"official baseball 720p estimate fits the same cap");check(!hlsExceedsLimit(longVideo,1400000,capacity::maxAssetBytes),"official 480p remains the next fallback");
 check(!hlsExceedsLimit(longVideo,0,capacity::maxAssetBytes),"unknown bitrate leaves actual-byte validation authoritative");check(lowerHlsHeight(1080)==720&&lowerHlsHeight(720)==480&&lowerHlsHeight(480)==0,"quality fallback is bounded and never invents a lower URL");
 bool noLower=false;try{hlsPlan("#EXTM3U\n#EXT-X-STREAM-INF:BANDWIDTH=5800000,RESOLUTION=1920x1080\n1080.m3u8\n","https://video.steamstatic.com/master.m3u8",720);}catch(const std::exception&e){noLower=std::string(e.what())=="media-size-invalid";}check(noLower,"absent lower official quality stops instead of repeating the same playlist");
 // Reuse this quality-selection test; no download/decoder or new parent gate.
 Json fpsSelections=Json::array();
 const auto choose=[&](const char* name,const std::string& manifest,int ceiling=0,int preferred=720){const auto p=hlsPlan(manifest,"https://video.steamstatic.com/fps/master.m3u8",ceiling,preferred);fpsSelections.push_back(Json{{"case",name},{"variant",p.variant},{"height",p.height},{"bandwidth",p.bandwidth},{"frameRate",p.frameRate>0?Json(p.frameRate):Json(nullptr)},{"frameRateSource",p.frameRate>0?"manifest":"unknown"}});return p;};
 const auto variant=[](int height,const std::string& fps,int bandwidth,const char* name){return "#EXT-X-STREAM-INF:BANDWIDTH="+std::to_string(bandwidth)+",RESOLUTION=1280x"+std::to_string(height)+(fps.empty()?"":",FRAME-RATE="+fps)+"\n"+name+"\n";};
 const auto mixed="#EXTM3U\n"+variant(720,"60",6000000,"720-60.m3u8")+variant(720,"30",2000000,"720-30.m3u8")+variant(480,"30",1000000,"480-30.m3u8");
 auto fpsPlan=choose("same-height-30-over-60",mixed);check(fpsPlan.variant.ends_with("/720-30.m3u8")&&fpsPlan.frameRate==30,"same-height 30fps beats higher-bitrate 60fps");
 fpsPlan=choose("default-480-30-over-720-60","#EXTM3U\n"+variant(720,"60",6000000,"720-60.m3u8")+variant(480,"29.970",1000000,"480-2997.m3u8"));check(fpsPlan.height==480&&std::abs(fpsPlan.frameRate-29.97)<0.000001,"default 480p 29.97fps beats 720p 60fps");
 fpsPlan=choose("known-30-over-unknown","#EXTM3U\n"+variant(720,"",6000000,"720-unknown.m3u8")+variant(480,"30",1000000,"480-30.m3u8"));check(fpsPlan.height==480&&fpsPlan.frameRate==30,"known <=30fps preferred within default band over unknown fps");
 fpsPlan=choose("only-60-stays-downloadable","#EXTM3U\n"+variant(720,"60",6000000,"720-60.m3u8")+variant(480,"60",1000000,"480-60.m3u8"));check(fpsPlan.height==720&&fpsPlan.frameRate==60,"all-60fps sources remain usable with preferred height");
